fn next_fork_capacity_keeps_every_full_arithmetic_path_and_original_work() {
    let mut source = String::from("module next_fork; @id(\"f\") fn f(x:i64)->i64 {");
    for index in 0..96 {
        let input = if index == 0 {
            "x".to_owned()
        } else {
            format!("x{}", index - 1)
        };
